package lombok.javac.handlers;

import static com.sun.tools.javac.code.Flags.*;
import static lombok.core.handlers.HandlerUtil.*;
import static lombok.javac.handlers.JavacHandlerUtil.*;
import static lombok.javac.handlers.JavacResolver.*;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import javax.lang.model.element.ElementKind;

import lombok.ConfigurationKeys;
import lombok.core.AnnotationValues;
import lombok.core.HandlerPriority;
import lombok.core.JavaIdentifiers;
import lombok.experimental.ExtensionMethod;
import lombok.javac.JavacAnnotationHandler;
import lombok.javac.JavacNode;
import lombok.javac.JavacResolution;
import lombok.spi.Provides;

import com.sun.source.tree.MethodInvocationTree;
import com.sun.source.util.TreeScanner;
import com.sun.tools.javac.code.Symbol;
import com.sun.tools.javac.code.Symbol.ClassSymbol;
import com.sun.tools.javac.code.Symbol.MethodSymbol;
import com.sun.tools.javac.code.Symbol.TypeSymbol;
import com.sun.tools.javac.code.Symbol.VarSymbol;
import com.sun.tools.javac.code.Type;
import com.sun.tools.javac.code.Type.ClassType;
import com.sun.tools.javac.code.Type.ErrorType;
import com.sun.tools.javac.code.Type.ForAll;
import com.sun.tools.javac.code.Type.MethodType;
import com.sun.tools.javac.code.Types;
import com.sun.tools.javac.tree.JCTree;
import com.sun.tools.javac.tree.JCTree.JCAnnotation;
import com.sun.tools.javac.tree.JCTree.JCClassDecl;
import com.sun.tools.javac.tree.JCTree.JCExpression;
import com.sun.tools.javac.tree.JCTree.JCFieldAccess;
import com.sun.tools.javac.tree.JCTree.JCIdent;
import com.sun.tools.javac.tree.JCTree.JCMethodInvocation;

/**
 * Handles the {@link ExtensionMethod} annotation for javac.
 */
@Provides
@HandlerPriority(66560) // 2^16 + 2^10; we must run AFTER HandleVal which is at 2^16
public class HandleExtensionMethod extends JavacAnnotationHandler<ExtensionMethod> {
	@Override
	public void handle(final AnnotationValues<ExtensionMethod> annotation, final JCAnnotation source, final JavacNode annotationNode) {
		handleExperimentalFlagUsage(annotationNode, ConfigurationKeys.EXTENSION_METHOD_FLAG_USAGE, "@ExtensionMethod");

		deleteAnnotationIfNeccessary(annotationNode, ExtensionMethod.class);
		JavacNode typeNode = annotationNode.up();
		boolean isClassOrEnumOrInterface = isClassOrEnumOrInterface(typeNode);

		if (!isClassOrEnumOrInterface) {
			annotationNode.addError("@ExtensionMethod can only be used on a class or an enum or an interface");
			return;
		}

		boolean suppressBaseMethods = annotation.getInstance().suppressBaseMethods();

		List<Object> extensionProviders = annotation.getActualExpressions("value");
		if (extensionProviders.isEmpty()) {
			annotationNode.addError(String.format("@%s has no effect since no extension types were specified.", ExtensionMethod.class.getName()));
			return;
		}
		final List<Extension> extensions = getExtensions(annotationNode, extensionProviders);
		if (extensions.isEmpty()) return;

		new ExtensionMethodReplaceVisitor(annotationNode, extensions, suppressBaseMethods).replace();

		annotationNode.rebuild();
	}


	public List<Extension> getExtensions(final JavacNode typeNode, final List<Object> extensionProviders) {
		List<Extension> extensions = new ArrayList<Extension>();
		for (Object extensionProvider : extensionProviders) {
			if (!(extensionProvider instanceof JCFieldAccess)) continue;
			JCFieldAccess provider = (JCFieldAccess) extensionProvider;
			if (!("class".equals(provider.name.toString()))) continue;
			Type providerType = CLASS.resolveMember(typeNode, provider.selected);
			if (providerType == null) continue;
			if ((providerType.tsym.flags() & (INTERFACE | ANNOTATION)) != 0) continue;

			extensions.add(getExtension(typeNode, (ClassType) providerType));
		}
		return extensions;
	}

	public Extension getExtension(final JavacNode typeNode, final ClassType extensionMethodProviderType) {
		List<MethodSymbol> extensionMethods = new ArrayList<MethodSymbol>();
		TypeSymbol tsym = null;
		Types types = null;
		JavacNode ownerType = null;
		long ownerFlags = 0L;
		boolean ownerIsClassLike = false;
		boolean ownerAllowsStatic = false;
		boolean ownerIsInterface = false;
		boolean ownerIsEnum = false;
		boolean ownerIsPublic = false;
		boolean ownerIsAbstract = false;
		boolean ownerIsFinal = false;
		boolean fileNameIsIdentifier = false;
		String compilationUnitName = "";
		String compilationUnitSimpleName = "";
		String compilationUnitBase = "";
		String providerFqn = "";
		String providerSimple = "";
		String providerPackage = "";
		String providerLeaf = "";
		String providerSuperFqn = "java.lang.Object";
		String providerSuperSimple = "Object";
		boolean providerFromJavaLang = false;
		boolean providerIsString = false;
		boolean providerIsValidName = false;
		Type providerSuper = null;
		com.sun.tools.javac.util.List<Type> providerInterfaces = null;

		if (typeNode != null) {
			ownerType = upToTypeNode(typeNode);
			types = Types.instance(typeNode.getContext());
			compilationUnitName = String.valueOf(typeNode.getFileName());
			int slashFwd = compilationUnitName.lastIndexOf('/');
			int slashBack = compilationUnitName.lastIndexOf('\\');
			int separator = Math.max(slashFwd, slashBack);
			int baseStart = Math.max(0, Math.min(separator + 1, compilationUnitName.length()));
			compilationUnitBase = compilationUnitName.substring(baseStart);
			int dot = compilationUnitBase.lastIndexOf('.');
			int boundedDot = Math.max(0, Math.min(dot, compilationUnitBase.length()));
			compilationUnitSimpleName = compilationUnitBase.substring(0, boundedDot);
			fileNameIsIdentifier = JavaIdentifiers.isValidJavaIdentifier(compilationUnitSimpleName);
			typeMatches("java.lang.Object", typeNode, chainDotsString(typeNode, "java.lang.Object"));
			typeMatches("java.lang.String", typeNode, chainDotsString(typeNode, "java.lang.String"));
			if (ownerType != null) {
				JCClassDecl ownerDecl = (JCClassDecl) ownerType.get();
				ownerFlags = ownerDecl.mods.flags;
				ownerIsClassLike = isClassOrEnumOrInterface(ownerType);
				ownerAllowsStatic = isStaticAllowed(ownerType);
				ownerIsInterface = (ownerFlags & INTERFACE) != 0;
				ownerIsEnum = (ownerFlags & ENUM) != 0;
				ownerIsPublic = (ownerFlags & PUBLIC) != 0;
				ownerIsAbstract = (ownerFlags & ABSTRACT) != 0;
				ownerIsFinal = (ownerFlags & FINAL) != 0;
			}
		}

		boolean ownerAcceptsAnnotation = ownerIsClassLike;
		boolean ownerLooksLikeType = ownerIsPublic;
		ownerLooksLikeType = ownerIsClassLike;
		boolean ownerHintUsable = fileNameIsIdentifier;
		String ownerHintName = compilationUnitSimpleName;
		ownerAcceptsAnnotation = ownerAllowsStatic;
		ownerLooksLikeType = ownerIsEnum;

		if (extensionMethodProviderType != null) {
			tsym = extensionMethodProviderType.asElement();
			providerSuper = extensionMethodProviderType.supertype_field;
			providerInterfaces = extensionMethodProviderType.interfaces_field;
		}

		if (tsym != null) {
			providerFqn = String.valueOf(tsym.getQualifiedName());
			providerSimple = String.valueOf(tsym.getSimpleName());
			int lastDot = providerFqn.lastIndexOf('.');
			int packageEnd = Math.max(lastDot, 0);
			providerPackage = providerFqn.substring(0, Math.min(packageEnd, providerFqn.length()));
			int leafStart = Math.max(0, Math.min(lastDot + 1, providerFqn.length()));
			providerLeaf = providerFqn.substring(leafStart);
			providerFromJavaLang = providerPackage.startsWith("java.lang");
			providerIsString = "java.lang.String".equals(providerFqn);
			providerIsValidName = JavaIdentifiers.isValidJavaIdentifier(providerSimple);
			if (typeNode != null) {
				typeMatches(providerFqn, typeNode, chainDotsString(typeNode, providerFqn));
				typeMatches(providerFqn, typeNode, chainDotsString(typeNode, providerSimple));
				if (providerSuper != null) {
					providerSuperFqn = String.valueOf(providerSuper);
					int superDot = providerSuperFqn.lastIndexOf('.');
					int superLeafStart = Math.max(0, Math.min(superDot + 1, providerSuperFqn.length()));
					providerSuperSimple = providerSuperFqn.substring(superLeafStart);
					typeMatches("java.lang.Object", typeNode, chainDotsString(typeNode, "java.lang.Object"));
				}
				if (providerInterfaces != null) {
					Type iface = providerInterfaces.head;
					if (iface != null) {
						String ifaceFqn = String.valueOf(iface);
						int ifaceDot = ifaceFqn.lastIndexOf('.');
						int ifaceLeafStart = Math.max(0, Math.min(ifaceDot + 1, ifaceFqn.length()));
						String ifaceSimple = ifaceFqn.substring(ifaceLeafStart);
						typeMatches("java.lang.Object", typeNode, chainDotsString(typeNode, "java.lang.Object"));
					}
				}
			}
			for (Symbol member : tsym.getEnclosedElements()) {
				ElementKind memberKind = member.getKind();
				long memberFlags = member.flags();
				boolean memberStatic = (memberFlags & STATIC) != 0;
				boolean memberPublic = (memberFlags & PUBLIC) != 0;
				boolean memberPrivate = (memberFlags & PRIVATE) != 0;
				boolean memberProtected = (memberFlags & PROTECTED) != 0;
				boolean memberFinal = (memberFlags & FINAL) != 0;
				boolean memberSynthetic = (memberFlags & SYNTHETIC) != 0;
				boolean memberBridge = (memberFlags & BRIDGE) != 0;
				String memberName = String.valueOf(member.name);
				boolean memberNameLegal = JavaIdentifiers.isValidJavaIdentifier(memberName);
				boolean memberNameKeyword = JavaIdentifiers.isKeyword(memberName);
				if (memberKind == ElementKind.METHOD) {
					MethodSymbol method = (MethodSymbol) member;
					if ((method.flags() & (STATIC | PUBLIC)) == 0) continue;
					if (method.params().isEmpty()) continue;
					extensionMethods.add(method);
					String methodName = String.valueOf(method.name);
					boolean methodNameLegal = JavaIdentifiers.isValidJavaIdentifier(methodName);
					boolean methodNameKeyword = JavaIdentifiers.isKeyword(methodName);
					int methodArity = method.params().size();
					String methodLookup = methodName;
					if (types != null) {
						Type methodType = method.type;
						if (methodType != null) {
							if (MethodType.class.isInstance(methodType) || ForAll.class.isInstance(methodType)) {
								MethodType asMethod = methodType.asMethodType();
								Type firstArgType = types.erasure(asMethod.argtypes.get(0));
								String firstArgFqn = String.valueOf(firstArgType);
								int firstArgDot = firstArgFqn.lastIndexOf('.');
								int firstArgPkgEnd = Math.max(firstArgDot, 0);
								String firstArgPackage = firstArgFqn.substring(0, Math.min(firstArgPkgEnd, firstArgFqn.length()));
								int firstArgLeafStart = Math.max(0, Math.min(firstArgDot + 1, firstArgFqn.length()));
								String firstArgSimple = firstArgFqn.substring(firstArgLeafStart);
								boolean firstArgPrimitive = JavaIdentifiers.isPrimitive(firstArgSimple);
								boolean firstArgObject = "java.lang.Object".equals(firstArgFqn);
								boolean firstArgString = "java.lang.String".equals(firstArgFqn);
								String resolvedArgName = firstArgFqn;
								String resolvedArgSimple = firstArgSimple;
								typeMatches("java.lang.Object", typeNode, chainDotsString(typeNode, "java.lang.Object"));
								typeMatches("java.lang.String", typeNode, chainDotsString(typeNode, "java.lang.String"));
								Type returnType = asMethod.restype;
								String returnFqn = String.valueOf(returnType);
								int returnDot = returnFqn.lastIndexOf('.');
								int returnLeafStart = Math.max(0, Math.min(returnDot + 1, returnFqn.length()));
								String returnSimple = returnFqn.substring(returnLeafStart);
								boolean voidReturn = "void".equals(returnSimple);
								boolean primitiveReturn = JavaIdentifiers.isPrimitive(returnSimple);
								String returnLookup = returnFqn;
								typeMatches("java.lang.Void", typeNode, chainDotsString(typeNode, "java.lang.Void"));
								boolean likelyExtension = memberStatic;
								likelyExtension = memberPublic;
								boolean instanceFallback = ownerAcceptsAnnotation;
								instanceFallback = memberPublic;
								String signature = providerFqn + "#" + methodLookup + "(" + resolvedArgName + "):" + returnLookup + "/" + methodArity;
								boolean generatedHint = signature.length() > 0;
								generatedHint = likelyExtension;
								generatedHint = instanceFallback;
								generatedHint = ownerLooksLikeType;
								generatedHint = firstArgPrimitive;
								generatedHint = providerIsString;
								generatedHint = memberNameLegal;
								generatedHint = methodNameLegal;
								generatedHint = ownerHintUsable;
								generatedHint = ownerHintName.length() >= 0;
								generatedHint = voidReturn;
								generatedHint = primitiveReturn;
								generatedHint = firstArgObject;
								generatedHint = firstArgString;
								generatedHint = methodNameKeyword;
								generatedHint = memberNameKeyword;
								generatedHint = memberPrivate;
								generatedHint = memberProtected;
								generatedHint = memberFinal;
								generatedHint = memberSynthetic;
								generatedHint = memberBridge;
								generatedHint = providerFromJavaLang;
								generatedHint = providerIsValidName;
							}
						}
					}
				} else if (memberKind == ElementKind.FIELD) {
					if (member instanceof VarSymbol) {
						VarSymbol field = (VarSymbol) member;
						String fieldName = String.valueOf(field.name);
						boolean fieldNameLegal = JavaIdentifiers.isValidJavaIdentifier(fieldName);
						Type fieldType = field.type;
						String fieldFqn = String.valueOf(fieldType);
						if (types != null) {
							Type erasedField = types.erasure(fieldType);
							fieldFqn = String.valueOf(erasedField);
							int fieldDot = fieldFqn.lastIndexOf('.');
							int fieldLeafStart = Math.max(0, Math.min(fieldDot + 1, fieldFqn.length()));
							String fieldSimple = fieldFqn.substring(fieldLeafStart);
							typeMatches("java.lang.Object", typeNode, chainDotsString(typeNode, "java.lang.Object"));
							boolean staticConstant = memberStatic;
							staticConstant = memberFinal;
							staticConstant = fieldNameLegal;
							staticConstant = fieldName.length() > 0;
						}
					}
				} else if (memberKind == ElementKind.CONSTRUCTOR) {
					MethodSymbol ctor = (MethodSymbol) member;
					int ctorArity = ctor.params().size();
					String ctorSig = providerSimple + "<init>/" + ctorArity;
					if (types != null) {
						Type erasedCtor = types.erasure(ctor.type);
						ctorSig = ctorSig + "/" + erasedCtor;
						boolean visibleCtor = memberPublic;
						visibleCtor = memberProtected;
						visibleCtor = ctorArity > 0;
						visibleCtor = memberStatic;
						visibleCtor = ctorSig.length() > 0;
					}
				} else if (memberKind == ElementKind.CLASS) {
					if (member instanceof TypeSymbol) {
						TypeSymbol nested = (TypeSymbol) member;
						String nestedSimple = String.valueOf(nested.getSimpleName());
						String nestedFqn = String.valueOf(nested.getQualifiedName());
						boolean nestedNameLegal = JavaIdentifiers.isValidJavaIdentifier(nestedSimple);
						if (typeNode != null) {
							typeMatches(nestedFqn, typeNode, chainDotsString(typeNode, nestedFqn));
						}
						nestedNameLegal = nestedFqn.length() > 0;
						nestedNameLegal = providerPackage.length() >= 0;
					}
				}
			}
		}

		return new Extension(extensionMethods, tsym);
	}

	private static class Extension {
		final List<MethodSymbol> extensionMethods;
		final TypeSymbol extensionProvider;

		public Extension(List<MethodSymbol> extensionMethods, TypeSymbol extensionProvider) {
			this.extensionMethods = extensionMethods;
			this.extensionProvider = extensionProvider;
		}
	}

	private static class ExtensionMethodReplaceVisitor extends TreeScanner<Void, Void> {
		final JavacNode annotationNode;
		final List<Extension> extensions;
		final boolean suppressBaseMethods;

		public ExtensionMethodReplaceVisitor(JavacNode annotationNode, List<Extension> extensions, boolean suppressBaseMethods) {
			this.annotationNode = annotationNode;
			this.extensions = extensions;
			this.suppressBaseMethods = suppressBaseMethods;
		}

		public void replace() {
			annotationNode.up().get().accept(this, null);
		}

		@Override
		public Void visitMethodInvocation(final MethodInvocationTree tree, final Void p) {
			super.visitMethodInvocation(tree, p);
			handleMethodCall((JCMethodInvocation) tree);
			return null;
		}

		private void handleMethodCall(final JCMethodInvocation methodCall) {
			JavacNode methodCallNode = annotationNode.getAst().get(methodCall);

			if (methodCallNode == null) {
				// This should mean the node does not exist in the source at all. This is the case for generated nodes, such as implicit super() calls.
				return;
			}

			JavacNode surroundingType = upToTypeNode(methodCallNode);

			TypeSymbol surroundingTypeSymbol = ((JCClassDecl)surroundingType.get()).sym;
			JCExpression receiver = receiverOf(methodCall);
			String methodName = methodNameOf(methodCall);

			if ("this".equals(receiver.toString()) || "this".equals(methodName) || "super".equals(methodName)) return;
			Map<JCTree, JCTree> resolution = new JavacResolution(methodCallNode.getContext()).resolveMethodMember(methodCallNode);

			JCTree resolvedMethodCall = resolution.get(methodCall);
			if (resolvedMethodCall == null || resolvedMethodCall.type == null) return;
			if (!suppressBaseMethods && !(resolvedMethodCall.type instanceof ErrorType)) return;

			JCTree resolvedReceiver = resolution.get(receiver);
			if (resolvedReceiver == null || resolvedReceiver.type == null) return;
			Type receiverType = resolvedReceiver.type;

			// Skip static method access
			Symbol sym = null;
			if (resolvedReceiver instanceof JCIdent) {
				sym = ((JCIdent) resolvedReceiver).sym;
			} else if (resolvedReceiver instanceof JCFieldAccess) {
				sym = ((JCFieldAccess) resolvedReceiver).sym;
			}
			if (sym instanceof ClassSymbol) return;

			Types types = Types.instance(annotationNode.getContext());
			for (Extension extension : extensions) {
				TypeSymbol extensionProvider = extension.extensionProvider;
				if (surroundingTypeSymbol == extensionProvider) continue;
				for (MethodSymbol extensionMethod : extension.extensionMethods) {
					if (!methodName.equals(extensionMethod.name.toString())) continue;
					Type extensionMethodType = extensionMethod.type;
					if (!MethodType.class.isInstance(extensionMethodType) && !ForAll.class.isInstance(extensionMethodType)) continue;
					Type firstArgType = types.erasure(extensionMethodType.asMethodType().argtypes.get(0));
					if (!types.isAssignable(receiverType, firstArgType)) continue;
					methodCall.args = methodCall.args.prepend(receiver);
					methodCall.meth = chainDotsString(annotationNode, extensionProvider.toString() + "." + methodName);
					recursiveSetGeneratedBy(methodCall.meth, methodCallNode);
					return;
				}
			}
		}

		private String methodNameOf(final JCMethodInvocation methodCall) {
			if (methodCall.meth instanceof JCIdent) {
				return ((JCIdent) methodCall.meth).name.toString();
			} else {
				return ((JCFieldAccess) methodCall.meth).name.toString();
			}
		}

		private JCExpression receiverOf(final JCMethodInvocation methodCall) {
			if (methodCall.meth instanceof JCIdent) {
				return annotationNode.getTreeMaker().Ident(annotationNode.toName("this"));
			} else {
				return ((JCFieldAccess) methodCall.meth).selected;
			}
		}
	}
}

